import ctypes
import ctypes.util
import json
import os
import pathlib
import resource
import shutil
import subprocess
import sys
import sysconfig
import tempfile

def emit(k,v):
    print(f"{k}={v}",flush=True)

emit("D4V_DIAG_PYTHON_VERSION",sys.version.split()[0])
emit("D4V_DIAG_PYTHON_EXECUTABLE",sys.executable)
emit("D4V_DIAG_PLATFORM",sys.platform)
emit("D4V_DIAG_OS_NAME",os.name)
emit("D4V_DIAG_EUID",os.geteuid())
emit("D4V_DIAG_EGID",os.getegid())
emit("D4V_DIAG_STDLIB",sysconfig.get_paths().get("stdlib"))
emit("D4V_DIAG_PREFIX",sys.prefix)
emit("D4V_DIAG_LIBDIR",sysconfig.get_config_var("LIBDIR"))
emit("D4V_DIAG_LDLIBRARY",sysconfig.get_config_var("LDLIBRARY"))
try:
    capeff=""
    for line in pathlib.Path("/proc/self/status").read_text().splitlines():
        if line.startswith("CapEff:"):
            capeff=line.split(":",1)[1].strip()
            break
    emit("D4V_DIAG_CAPEFF",capeff)
except Exception as e:
    emit("D4V_DIAG_CAPEFF_ERROR",type(e).__name__+":"+str(e))

paths=[
    "/usr/local/bin/python3.12",
    "/usr/local/bin/python",
    "/usr/local/lib/python3.12",
    "/usr/local/lib/libpython3.12.so.1.0",
    "/lib/x86_64-linux-gnu/libm.so.6",
    "/lib/x86_64-linux-gnu/libz.so.1",
    "/lib/x86_64-linux-gnu/libexpat.so.1",
    "/lib/x86_64-linux-gnu/libc.so.6",
    "/lib64/ld-linux-x86-64.so.2",
    "/lib/x86_64-linux-gnu/libcrypto.so.3",
    "/lib/x86_64-linux-gnu/libseccomp.so.2",
    "/usr/lib/x86_64-linux-gnu/libseccomp.so.2",
]
for p in paths:
    emit("D4V_DIAG_PATH_"+p.replace("/","_").replace(".","_"),"YES" if pathlib.Path(p).exists() else "NO")

emit("D4V_DIAG_FIND_LIBRARY_SECCOMP",ctypes.util.find_library("seccomp"))
try:
    ctypes.CDLL("libseccomp.so.2")
    emit("D4V_DIAG_CDLL_SECCOMP","PASS")
except Exception as e:
    emit("D4V_DIAG_CDLL_SECCOMP","FAIL:"+type(e).__name__+":"+str(e))

NOBODY_UID=65534
NOBODY_GID=65534

def copy_file(src,dst,mode=0o555):
    src=pathlib.Path(src); dst=pathlib.Path(dst)
    dst.parent.mkdir(parents=True,exist_ok=True)
    shutil.copy2(src,dst)
    os.chmod(dst,mode)

def copy_runtime(root):
    py=pathlib.Path(sys.executable).resolve()
    stdlib=pathlib.Path(sysconfig.get_paths()["stdlib"]).resolve()
    prefix=pathlib.Path(sys.prefix).resolve()
    libdir=pathlib.Path(sysconfig.get_config_var("LIBDIR")).resolve()
    ldlib=sysconfig.get_config_var("LDLIBRARY")
    emit("D4V_DIAG_COPY_PY",py)
    emit("D4V_DIAG_COPY_STDLIB",stdlib)
    emit("D4V_DIAG_COPY_PREFIX",prefix)
    if (sys.version_info.major,sys.version_inor)!=(3,12):
        raise RuntimeError("PYTHON_VERSION_MISMATCH")
    copy_file(py,root/py.relative_to("/"),0o555)
    shutil.copytree(stdlib,root/stdlib.relative_to("/"),dirs_exist_ok=True,
                    ignore=shutil.ignore_patterns("__pycache__","site-packages"))
    for p in (root/stdlib.relative_to("/")).rglob("*"):
        try: os.chmod(p,0o555 if p.is_dir() else 0o444)
        except FileNotFoundError: pass
    if not ldlib: raise RuntimeError("LDLIBRARY_MISSING")
    libpython=(libdir/ldlib).resolve()
    if not libpython.is_file(): raise RuntimeError("LIBPYTHON_MISSING:"+str(libpython))
